    )


def _workbook_fingerprint(workbook: Path) -> dict[str, str]:
    digest = hashlib.sha256()
    with workbook.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    stat = workbook.stat()
    return {
        "workbook_path": str(workbook),
        "workbook_size": str(stat.st_size),
        "workbook_mtime": str(stat.st_mtime_ns),
        "workbook_sha256": digest.hexdigest(),
    }


@contextmanager
def _build_lock(database: Path, timeout_seconds: float = 300.0):
    lock = Path(f"{database}.build.lockfile")
    lock.parent.mkdir(parents=True, exist_ok=True)
    deadline = time.monotonic() + timeout_seconds
    with lock.open("a+b") as handle:
        handle.seek(0)
        if handle.read(1) == b"":
            handle.write(b"0")
            handle.flush()
        while True:
            try:
                if os.name == "nt":
                    import msvcrt

                    handle.seek(0)
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl

                    fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except (OSError, BlockingIOError):
                if time.monotonic() >= deadline:
                    raise TimeoutError(f"Timed out waiting for preprocessing lock: {lock}")
                time.sleep(0.1)
        try:
            yield
        finally:
            if os.name == "nt":
                handle.seek(0)
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def _read_metadata(connection: sqlite3.Connection) -> dict[str, str]:
