def _records(frame: pd.DataFrame) -> list[dict]:
    return json.loads(frame.where(pd.notna(frame), None).to_json(orient="records", force_ascii=False))


def _schema(frame: pd.DataFrame) -> list[dict]:
    return [
        {
            "column": column,
            "dtype": str(frame[column].dtype),
            "sample_values": frame[column].dropna().astype(str).loc[lambda values: values.str.strip() != ""].head(3).tolist(),
        }
        for column in frame.columns
    ]


def _normalize_study_mode(frame: pd.DataFrame) -> None:
    if "Opleidingsvorm" not in frame.columns:
        return
    normalized = frame["Opleidingsvorm"].astype("string").str.strip()
    frame["Opleidingsvorm"] = normalized.replace(
        {"vt": "Voltijd", "voltijdopleiding": "Voltijd", "dt": "Deeltijd", "deeltijdopleiding": "Deeltijd"}
    )


def _extract_spacy_entities(open_answers: pd.DataFrame, metadata_columns: list[str], model_name: str) -> pd.DataFrame:
    import spacy

    nlp = spacy.load(model_name)
    rows = []
    texts = open_answers["answer_clean"].astype(str).tolist()
    for source_row, document in zip(open_answers.itertuples(index=False), nlp.pipe(texts, batch_size=64), strict=True):
        for entity in document.ents:
            text_value = entity.text.strip()
            if not text_value:
                continue
            row = {
                "response_row_id": int(source_row.response_row_id),
                "question_column": source_row.question_column,
                "answer_clean": source_row.answer_clean,
                "entity_text": text_value,
                "entity_label": entity.label_,
            }
            row.update({column: getattr(source_row, column) for column in metadata_columns if hasattr(source_row, column)})
            rows.append(row)
    return pd.DataFrame(rows, columns=[
        "response_row_id", "question_column", "answer_clean", "entity_text", "entity_label", *metadata_columns,
    ])


def prepare_sqlite_survey(
    workbook_path: str,
    sheet_name: str = "",
    database_path: str = "",
) -> dict:
    workbook = Path(workbook_path).expanduser().resolve()
    if not workbook.exists():
        raise FileNotFoundError(f"Workbook not found: {workbook}")
    excel_file = pd.ExcelFile(workbook)
    selected_sheet = sheet_name.strip() or excel_file.sheet_names[0]
    if selected_sheet not in excel_file.sheet_names:
        raise ValueError(f"Worksheet '{selected_sheet}' not found. Available: {excel_file.sheet_names}")
    source = pd.read_excel(workbook, sheet_name=selected_sheet)
    source.columns = [str(column).strip() for column in source.columns]
    if source.empty:
        raise ValueError(f"Worksheet '{selected_sheet}' contains no rows.")
    _normalize_study_mode(source)
    open_answers, answer_columns, metadata_columns = normalize_open_answers(source)
    source_table = normalize_sql_name(selected_sheet)
    open_answers_table = f"{source_table}_open_answers"
    entity_table = f"{source_table}_entities"
    ngram_table = f"{source_table}_ngrams"
    ngram_summary_table = f"{source_table}_ngram_summary"
    target_database = Path(database_path).expanduser().resolve() if database_path else workbook.with_suffix(".sqlite")
    target_database.parent.mkdir(parents=True, exist_ok=True)
    with sqlite3.connect(target_database) as connection:
        source.to_sql(source_table, connection, if_exists="replace", index=False)
        open_answers.to_sql(open_answers_table, connection, if_exists="replace", index=False)
        pd.DataFrame(columns=[
            "response_row_id", "question_column", "answer_clean", "entity_text", "entity_label", *metadata_columns,
        ]).to_sql(entity_table, connection, if_exists="replace", index=False)
        connection.execute("CREATE TABLE IF NOT EXISTS _survey_metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
        metadata = {
            "cache_schema_version": CACHE_SCHEMA_VERSION,
            "normalization_version": NORMALIZATION_VERSION,
            **_workbook_fingerprint(workbook),
            "sheet_name": selected_sheet,
            "source_table": source_table,
            "open_answers_table": open_answers_table,
            "spacy_entities_table": entity_table,
            "ngram_table": ngram_table,
            "ngram_summary_table": ngram_summary_table,
            "spacy_model": "",
            "schema": json.dumps(_schema(source), ensure_ascii=False),
            "open_answer_columns": json.dumps(answer_columns, ensure_ascii=False),
            "metadata_columns": json.dumps(metadata_columns, ensure_ascii=False),
            "source_row_count": str(len(source)),
            "open_answer_count": str(len(open_answers)),
            "spacy_entity_count": "0",
            "ngram_config": "{}",
            "ngram_count": "0",
            "sqlite_complete": "true",
            "ner_complete": "false",
            "ngram_complete": "false",
        }
        connection.executemany(
            "INSERT OR REPLACE INTO _survey_metadata(key, value) VALUES (?, ?)", metadata.items()
        )
    return {
        "workbook_path": str(workbook),
        "sheet_name": selected_sheet,
        "database_path": str(target_database),
        "database_uri": f"sqlite:///{target_database.as_posix()}",
        "source_table": source_table,
        "open_answers_table": open_answers_table,
        "spacy_entities_table": entity_table,
        "ngram_table": ngram_table,
        "ngram_summary_table": ngram_summary_table,
        "schema": _schema(source),
        "open_answer_columns": answer_columns,
        "metadata_columns": metadata_columns,
        "source_row_count": len(source),
        "open_answer_count": len(open_answers),
        "spacy_entity_count": 0,
        "spacy_model": "",
        "ngram_config": {},
        "ngram_count": 0,
        "cache_status": "rebuilt",
        "ngram_cache_status": "not_built",
    }


def ensure_sqlite_survey(workbook_path: str, sheet_name: str = "", database_path: str = "") -> dict:
    workbook = Path(workbook_path).expanduser().resolve()
    if not workbook.exists():
        raise FileNotFoundError(f"Workbook not found: {workbook}")
    database = Path(database_path).expanduser().resolve() if database_path else workbook.with_suffix(".sqlite")
    database.parent.mkdir(parents=True, exist_ok=True)
    fingerprint = _workbook_fingerprint(workbook)
    with _build_lock(database):
        if database.exists():
            try:
                with sqlite3.connect(database) as connection:
                    metadata = _read_metadata(connection)
                    selected_sheet = sheet_name.strip() or metadata.get("sheet_name", "")
                    valid = (
                        metadata.get("cache_schema_version") == CACHE_SCHEMA_VERSION
                        and metadata.get("normalization_version") == NORMALIZATION_VERSION
                        and all(metadata.get(key) == value for key, value in fingerprint.items())
                        and metadata.get("sheet_name") == selected_sheet
                        and metadata.get("sqlite_complete") == "true"
                        and all(
                            _table_exists(connection, metadata.get(key, ""))
                            for key in ("source_table", "open_answers_table", "spacy_entities_table")
                        )
                    )
                if valid:
                    return _dataset_from_metadata(metadata, database)
            except (sqlite3.Error, KeyError, ValueError, json.JSONDecodeError):
                pass
        return prepare_sqlite_survey(str(workbook), sheet_name, str(database))


def build_ner_tables(dataset: dict, spacy_model: str = "nl_core_news_sm") -> dict:
    with sqlite3.connect(dataset["database_path"]) as connection:
        open_answers = _load_table(connection, dataset["open_answers_table"])
        entities = _extract_spacy_entities(open_answers, dataset["metadata_columns"], spacy_model)
        entities.to_sql(dataset["spacy_entities_table"], connection, if_exists="replace", index=False)
        connection.execute(
            "INSERT OR REPLACE INTO _survey_metadata(key, value) VALUES (?, ?)",
            ("spacy_model", spacy_model),
        )
        connection.executemany(
            "INSERT OR REPLACE INTO _survey_metadata(key, value) VALUES (?, ?)",
            (("spacy_entity_count", str(len(entities))), ("ner_complete", "true")),
        )
    return {
        **dataset,
        "spacy_entity_count": len(entities),
        "spacy_model": spacy_model,
        "cache_status": "rebuilt",
    }


def ensure_ner_tables(dataset: dict, spacy_model: str = "nl_core_news_sm") -> dict:
    database = Path(dataset["database_path"]).expanduser().resolve()
    with _build_lock(database):
        try:
            with sqlite3.connect(database) as connection:
                metadata = _read_metadata(connection)
                valid = (
                    metadata.get("cache_schema_version") == CACHE_SCHEMA_VERSION
                    and metadata.get("sqlite_complete") == "true"
                    and metadata.get("ner_complete") == "true"
                    and metadata.get("spacy_model") == spacy_model
                    and _table_exists(connection, metadata.get("spacy_entities_table", ""))
                )
            if valid:
                return _dataset_from_metadata(metadata, database)
        except (sqlite3.Error, KeyError, ValueError, json.JSONDecodeError):
            pass
        return build_ner_tables(dataset, spacy_model)


def _normalized_ngram_config(config: dict) -> dict:
    normalized = {
        "min_n": int(config.get("min_n", 2)),
        "max_n": int(config.get("max_n", 3)),
        "minimum_frequency": int(config.get("minimum_frequency", 3)),
        "use_lemmas": bool(config.get("use_lemmas", True)),
        "remove_stopwords": bool(config.get("remove_stopwords", True)),
    }
    if not 1 <= normalized["min_n"] <= normalized["max_n"] <= 5:
        raise ValueError("N-gram sizes must satisfy 1 <= min_n <= max_n <= 5.")
    if normalized["minimum_frequency"] < 1:
        raise ValueError("Minimum n-gram frequency must be at least 1.")
    return normalized


def build_ngram_tables(dataset: dict, config: dict) -> dict:
    import spacy

    normalized_config = _normalized_ngram_config(config)
    model_name = dataset.get("spacy_model") or "nl_core_news_sm"
    nlp = spacy.load(model_name)
    with sqlite3.connect(dataset["database_path"]) as connection:
        answers = _load_table(connection, dataset["open_answers_table"])
        rows = []
        unique_dutch_words = set()
        texts = answers["answer_clean"].astype(str).tolist()
        for answer, document in zip(answers.to_dict(orient="records"), nlp.pipe(texts, batch_size=64), strict=True):
            if not is_probably_dutch(answer["answer_clean"]):
                continue
            segments = []
            segment = []
            for token in document:
                raw_value = token.lemma_ if normalized_config["use_lemmas"] and token.lemma_ else token.text
                value = normalize_token(raw_value).strip()
                valid_word = (
                    not token.is_space
                    and not token.is_punct
                    and not token.like_num
                    and bool(re.fullmatch(r"[a-zà-öø-ÿ][a-zà-öø-ÿ'-]*", value))
                )
                if valid_word:
                    unique_dutch_words.add(value)
                excluded = (
                    not valid_word
                    or (normalized_config["remove_stopwords"] and (token.is_stop or value in STOPWORDS_NL))
                )
                if excluded:
                    if segment:
                        segments.append(segment)
                        segment = []
                    continue
                segment.append(value)
            if segment:
                segments.append(segment)
            for tokens in segments:
                for size in range(normalized_config["min_n"], normalized_config["max_n"] + 1):
                    for index in range(len(tokens) - size + 1):
                        rows.append({
                            "response_row_id": int(answer["response_row_id"]),
                            "question_column": answer["question_column"],
                            "ngram": " ".join(tokens[index:index + size]),
                            "n": size,
                            **{column: answer.get(column) for column in dataset["metadata_columns"]},
                        })
        columns = ["response_row_id", "question_column", "ngram", "n", *dataset["metadata_columns"]]
        occurrences = pd.DataFrame(rows, columns=columns)
        if occurrences.empty:
            summary = pd.DataFrame(columns=["ngram", "n", "document_frequency", "total_frequency"])
        else:
            summary = occurrences.groupby(["ngram", "n"], as_index=False).agg(
                document_frequency=("response_row_id", "nunique"),
                total_frequency=("response_row_id", "size"),
            )
            summary = summary[summary["document_frequency"] >= normalized_config["minimum_frequency"]]
            occurrences = occurrences[occurrences["ngram"].isin(summary["ngram"])]
            summary = summary.sort_values(["document_frequency", "total_frequency", "ngram"], ascending=[False, False, True])
        occurrences.to_sql(dataset["ngram_table"], connection, if_exists="replace", index=False)
        summary.to_sql(dataset["ngram_summary_table"], connection, if_exists="replace", index=False)
        metadata = {
            "ngram_analyzer_version": NGRAM_ANALYZER_VERSION,
            "ngram_config": json.dumps(normalized_config, sort_keys=True),
            "ngram_count": str(len(summary)),
            "unique_dutch_word_count": str(len(unique_dutch_words)),
            "ngram_complete": "true",
        }
        connection.executemany(
            "INSERT OR REPLACE INTO _survey_metadata(key, value) VALUES (?, ?)", metadata.items()
        )
    return {
        **dataset,
        "ngram_config": normalized_config,
        "ngram_count": len(summary),
        "unique_dutch_word_count": len(unique_dutch_words),
        "ngram_cache_status": "rebuilt",
    }


def ensure_ngram_tables(dataset: dict, config: dict) -> dict:
    normalized_config = _normalized_ngram_config(config)
    database = Path(dataset["database_path"]).expanduser().resolve()
    with _build_lock(database):
        try:
            with sqlite3.connect(database) as connection:
                metadata = _read_metadata(connection)
                valid = (
                    metadata.get("cache_schema_version") == CACHE_SCHEMA_VERSION
                    and metadata.get("sqlite_complete") == "true"
                    and metadata.get("ngram_complete") == "true"
                    and metadata.get("ngram_analyzer_version") == NGRAM_ANALYZER_VERSION
                    and metadata.get("ngram_config") == json.dumps(normalized_config, sort_keys=True)
                    and _table_exists(connection, metadata.get("ngram_table", ""))
                    and _table_exists(connection, metadata.get("ngram_summary_table", ""))
                )
            if valid:
                return _dataset_from_metadata(metadata, database)
        except (sqlite3.Error, KeyError, ValueError, json.JSONDecodeError):
            pass
        return build_ngram_tables(dataset, normalized_config)


def prepare_survey(
    workbook_path: str,
    sheet_name: str = "",
    database_path: str = "",
    spacy_model: str = "nl_core_news_sm",
) -> dict:
    dataset = ensure_sqlite_survey(workbook_path, sheet_name, database_path)
    return ensure_ner_tables(dataset, spacy_model)


def ensure_survey(workbook_path: str, sheet_name: str, database_path: str, spacy_model: str) -> dict:
    return prepare_survey(workbook_path, sheet_name, database_path, spacy_model)


def _load_table(connection: sqlite3.Connection, table: str) -> pd.DataFrame:
    return pd.read_sql_query(f'SELECT * FROM "{table}"', connection)


def _filtered_answers(frame: pd.DataFrame, question_column: str | None) -> pd.DataFrame:
    working = frame.copy()
    if question_column:
        working = working[working["question_column"] == question_column]
    return working[~working["answer_clean"].astype(str).map(is_low_value_answer)]


def _top_keywords(frame: pd.DataFrame, top_n: int) -> pd.DataFrame:
    counter = Counter()
    for answer in frame["answer_clean"].astype(str):
        for token in normalize_token(answer).split():
            if len(token) >= 4 and token not in STOPWORDS_NL:
                counter[token] += 1
    return pd.DataFrame([{"keyword": key, "count": count} for key, count in counter.most_common(top_n)])


def _requests_ngram_analysis(question: str) -> bool:
    normalized = normalize_token(question)
    indicators = ("n gram", "ngram", "bigram", "trigram", "woordcombinatie", "frase", "formulering")
    return any(indicator in normalized for indicator in indicators)


def _requests_unique_dutch_word_count(question: str) -> bool:
    normalized = normalize_token(question)
    return "unieke" in normalized.split() and "woorden" in normalized.split() and "hoeveel" in normalized.split()


def _analyze_deterministic(
    route: dict, source: pd.DataFrame, answers: pd.DataFrame, entities: pd.DataFrame,
    ngrams: pd.DataFrame, top_n: int, unique_dutch_word_count: int = 0
) -> tuple[pd.DataFrame, str]:
    route_name = route["route"]
    if route_name == "deterministic_unique_dutch_words":
        return pd.DataFrame([{"unique_dutch_word_count": unique_dutch_word_count}]), "unique Dutch word count"
    selected = route["question_column"]
    working = _filtered_answers(answers, selected)
    if route_name == "deterministic_ngrams":
        data = ngrams.copy()
        if selected and not data.empty and "question_column" in data:
            data = data[data["question_column"] == selected]
        if data.empty:
            return pd.DataFrame(), "frequent n-grams"
        result = data.groupby(["ngram", "n"], as_index=False).agg(
            document_frequency=("response_row_id", "nunique"),
            total_frequency=("response_row_id", "size"),
        ).sort_values(["document_frequency", "total_frequency"], ascending=False).head(top_n)
        return result, "frequent n-grams"
    if route_name == "special_case_studielast":
        column = QUESTION_COLUMN_BY_TOPIC["studielast"]
        if "Opleidingsvorm" not in source or column not in source:
            return pd.DataFrame(), "study-load comparison"
        data = source[["Opleidingsvorm", column]].dropna().copy()
        data = data[~data[column].astype(str).map(is_low_value_answer)]
        result = data.groupby("Opleidingsvorm").agg(answer_count=(column, "size"), example=(column, "first")).reset_index()
        return result, "study-load comparison"
    if route_name.startswith("deterministic_named_entities"):
        data = entities.copy()
        if selected:
            data = data[data["question_column"] == selected]
        if route["entity_label"]:
            data = data[data["entity_label"] == route["entity_label"]]
        if data.empty:
            return pd.DataFrame(), "spaCy named entities"
        result = data.groupby(["entity_text", "entity_label"]).agg(
            mention_count=("entity_text", "size"), answer_count=("response_row_id", "nunique")
        ).reset_index().sort_values(["mention_count", "answer_count"], ascending=False).head(top_n)
        return result, "spaCy named entities"
    if route_name == "deterministic_docenten_feedback":
        return working[["answer_clean"]].head(min(top_n, 50)), "teacher feedback"
    if route_name in {"deterministic_examples_by_subgroup"}:
        subgroup = route["subgroup"]
        if not subgroup or subgroup not in working:
            return pd.DataFrame(), "representative examples"
        result = working.groupby(subgroup).agg(
            answer_count=("answer_clean", "size"), representative_example=("answer_clean", "first")
        ).reset_index().sort_values("answer_count", ascending=False)
        return result, f"representative examples by {subgroup}"
    if route_name in {"deterministic_welzijn_by_subgroup", "deterministic_top_themes_by_subgroup"}:
        subgroup = route["subgroup"] or "Opleidingsvorm"
        rows = []
        if subgroup in working:
            for group, subset in working.groupby(subgroup, dropna=True):
                for item in _records(_top_keywords(subset, top_n=5)):
                    rows.append({subgroup: group, **item})
        return pd.DataFrame(rows), f"top themes by {subgroup}"
    return _top_keywords(working, top_n), "top keywords/themes"


def _result_markdown(frame: pd.DataFrame) -> str:
    if frame.empty:
        return "Geen resultaten gevonden."
    try:
        return frame.to_markdown(index=False)
    except ImportError:
        return frame.to_string(index=False)


def _azure_client(endpoint: str, api_key: str, api_version: str):
    from openai import AzureOpenAI
    return AzureOpenAI(azure_endpoint=endpoint, api_key=api_key, api_version=api_version)


def _willma_client(base_url: str, api_key: str):
    from openai import OpenAI
    return OpenAI(base_url=base_url, api_key=api_key)


def _chat_completion(messages: list[dict[str, str]], llm_config: dict[str, str]) -> str:
    provider = llm_config["provider"]
    if provider == "azure":
        client = _azure_client(
            llm_config["endpoint"], llm_config["api_key"], llm_config["api_version"]
        )
    elif provider == "willma":
        client = _willma_client(llm_config["endpoint"], llm_config["api_key"])
    else:
        raise ValueError(f"Unsupported LLM provider: {provider}")
    response = client.chat.completions.create(model=llm_config["model"], messages=messages)
    content = response.choices[0].message.content
    if not content or not content.strip():
        raise ValueError(f"{provider} returned an empty chat completion.")
    return content.strip()


def _generate_sql(
    question: str,
    dataset: dict,
    llm_config: dict[str, str],
    row_limit: int,
    previous_error: str = "",
) -> str:
    target_table = dataset["open_answers_table"] if dataset["route"] == "sql_open_answers_table" else dataset["source_table"]
    schema = dataset["open_answer_schema"] if target_table == dataset["open_answers_table"] else dataset["schema"]
    schema_text = "\n".join(f"- {item['column']} ({item['dtype']})" for item in schema)
    prompt = (
        "Return exactly one read-only SQLite SELECT query without Markdown. "
        "For a request for all values, select DISTINCT values and sort them; do not add a LIMIT. "
        f"Use only table {target_table} and these columns:\n{schema_text}\nQuestion: {question}"
    )
    if previous_error:
        prompt += (
            f"\nThe previous query failed with this SQLite error: {previous_error}. "
            "Correct it using only the listed columns."
        )
    response_text = _chat_completion([{"role": "user", "content": prompt}], llm_config)
    return validate_select(response_text, {target_table}, row_limit)


def _execute_generated_sql(
    question: str,
    dataset: dict,
    llm_config: dict[str, str],
    row_limit: int,
    connection: sqlite3.Connection,
) -> tuple[pd.DataFrame, str]:
    sql_query = _generate_sql(question, dataset, llm_config, row_limit)
    try:
        return pd.read_sql_query(sql_query, connection), sql_query
    except pd.errors.DatabaseError as error:
        if "no such column" not in str(error).lower():
            raise
        sql_query = _generate_sql(question, dataset, llm_config, row_limit, str(error))
        return pd.read_sql_query(sql_query, connection), sql_query


def _has_invalid_dutch_output(text: str) -> bool:
    unexpected_script = re.search(
        r"[\u3400-\u4dbf\u4e00-\u9fff\u3040-\u30ff\u0400-\u04ff]", text
    )
    return not text.strip() or "## Antwoord" not in text or "## Resultaat" not in text or bool(unexpected_script)


def _summarize_result(
    question: str,
    result_markdown: str,
    llm_config: dict[str, str],
) -> tuple[str, str]:
    summary_prompt = (
        "Vat dit analyseresultaat kort en feitelijk samen in correct Nederlands met exact de secties "
        "## Antwoord en ## Resultaat. Voeg geen feiten toe en citeer alleen begrijpelijke brontekst. "
        f"\nVraag: {question}\nResultaat:\n{result_markdown}"
    )
    draft = _chat_completion([{"role": "user", "content": summary_prompt}], llm_config)
    correction_prompt = (
        "Redigeer het concept hieronder naar helder, grammaticaal correct Nederlands. "
        "Behoud exact de koppen ## Antwoord en ## Resultaat. Gebruik uitsluitend feiten uit het "
        "bronresultaat, voeg niets toe, verwijder onbegrijpelijke tekst en gebruik geen Chinese, "
        "Japanse of Cyrillische tekens. Geef alleen de gecorrigeerde tekst."
        f"\n\nVraag:\n{question}\n\nBronresultaat:\n{result_markdown}\n\nConcept:\n{draft}"
    )
    corrected = _chat_completion([{"role": "user", "content": correction_prompt}], llm_config)
    if _has_invalid_dutch_output(corrected):
        fallback = (
            "## Antwoord\nDe automatische Nederlandse samenvatting kon niet betrouwbaar worden "
            "gecorrigeerd. Hieronder staat het ongewijzigde analyseresultaat."
            f"\n\n## Resultaat\n{result_markdown}"
        )
        return fallback, "raw result fallback after language validation"
    return corrected, "validated Dutch summary"


def answer_question(
    question: str,
    workbook_path: str,
    sheet_name: str = "",
    database_path: str = "",
    spacy_model: str = "nl_core_news_sm",
    ngram_min_n: int = 2,
    ngram_max_n: int = 3,
    ngram_minimum_frequency: int = 3,
    ngram_use_lemmas: bool = True,
    ngram_remove_stopwords: bool = True,
    azure_endpoint: str = "",
    azure_api_key: str = "",
    azure_api_version: str = "",
    azure_deployment: str = "",
    llm_provider: str = "azure",
    willma_base_url: str = "",
    willma_api_key: str = "",
    willma_model: str = "",
    include_summary: bool = True,
    top_n: int = 15,
) -> dict:
    if not question.strip():
        raise ValueError("Question cannot be empty.")
    settings = _project_settings()
    workbook_path = _setting(workbook_path, settings, "DATASET_PATH")
    database_path = _setting(database_path, settings, "EXCEL_OPEN_ANSWERS_DB_PATH")
    azure_endpoint = _setting(azure_endpoint, settings, "AZURE_OPENAI_ENDPOINT")
    azure_api_key = _setting(azure_api_key, settings, "AZURE_OPENAI_API_KEY")
    azure_api_version = _setting(
        azure_api_version, settings, "AZURE_OPENAI_API_VERSION", "2024-12-01-preview"
    )
    azure_deployment = _setting(
        azure_deployment,
        settings,
        "AZURE_OPENAI_DEPLOYMENT",
        settings.get("AZURE_OPENAI_MODEL", "o3-mini"),
    )
    llm_provider = str(llm_provider or "azure").strip().lower()
    willma_base_url = _setting(willma_base_url, settings, "WILLMA_BASE_URL", "https://api.willma.surf.nl/v0")
    willma_api_key = _setting(willma_api_key, settings, "WILLMA_API_KEY")
    willma_model = _setting(willma_model, settings, "WILLMA_MODEL")
    if llm_provider == "azure":
        llm_config = {
            "provider": "azure",
            "endpoint": azure_endpoint,
            "api_key": azure_api_key,
            "api_version": azure_api_version,
            "model": azure_deployment,
        }
    elif llm_provider == "willma":
        llm_config = {
            "provider": "willma",
            "endpoint": willma_base_url,
            "api_key": willma_api_key,
            "api_version": "",
            "model": willma_model,
        }
    else:
        raise ValueError("LLM Provider must be 'azure' or 'willma'.")
    if not workbook_path:
        raise ValueError("Set Workbook Path in the component or DATASET_PATH in the project .env file.")
    dataset = ensure_survey(workbook_path, sheet_name, database_path, spacy_model)
    dataset = ensure_ngram_tables(dataset, {
        "min_n": ngram_min_n,
        "max_n": ngram_max_n,
        "minimum_frequency": ngram_minimum_frequency,
        "use_lemmas": ngram_use_lemmas,
        "remove_stopwords": ngram_remove_stopwords,
    })
    route = route_question(question, dataset["open_answer_columns"])
    if _requests_ngram_analysis(question):
        route = {**route, "route": "deterministic_ngrams"}
    elif _requests_unique_dutch_word_count(question):
        route = {**route, "route": "deterministic_unique_dutch_words"}
    with sqlite3.connect(dataset["database_path"]) as connection:
        source = _load_table(connection, dataset["source_table"])
        answers = _load_table(connection, dataset["open_answers_table"])
        entities = _load_table(connection, dataset["spacy_entities_table"])
        ngrams = _load_table(connection, dataset["ngram_table"])
        if route["route"].startswith("sql_"):
            missing = [name for name in ("endpoint", "api_key", "model") if not llm_config[name]]
            if missing:
                raise ValueError(
                    f"Missing {llm_provider} settings for SQL fallback: {', '.join(missing)}"
                )
            context = {**dataset, **route, "open_answer_schema": _schema(answers)}
            exhaustive = _requests_complete_list(question)
            row_limit = EXHAUSTIVE_RESULT_LIMIT if exhaustive else top_n
            result, sql_query = _execute_generated_sql(
                question, context, llm_config, row_limit, connection
            )
            operation = "validated SQLite SELECT"
        else:
            exhaustive = False
            result, operation = _analyze_deterministic(
                route, source, answers, entities, ngrams, top_n,
                dataset.get("unique_dutch_word_count", 0),
            )
            sql_query = None
    result_markdown = _result_markdown(result)
    if exhaustive:
        final_answer = (
            f"## Antwoord\nAlle gevonden unieke waarden ({len(result)})."
            f"\n\n## Resultaat\n{result_markdown}"
        )
    elif include_summary and llm_config["endpoint"] and llm_config["api_key"] and llm_config["model"]:
        final_answer, summary_status = _summarize_result(question, result_markdown, llm_config)
        operation = f"{operation}; {summary_status}"
    else:
        final_answer = f"## Antwoord\nAnalyse uitgevoerd via `{route['route']}`.\n\n## Resultaat\n{result_markdown}"
    return {
        "question": question,
        "route": route["route"],
        "selected_question_column": route["question_column"],
        "sql_query": sql_query,
        "diagnostics": {**route, "operation": operation, "database_path": dataset["database_path"]},
        "rows": _records(result),
        "result_markdown": result_markdown,
        "final_answer": final_answer,
    }

