import re
import unicodedata

import pandas as pd


LOW_VALUE_ANSWERS = {
    "", "-", ".", "...", "nvt", "n.v.t.", "nee", "geen", "geen opmerkingen",
    "geen opmerking", "niks", "niets", "nope",
}

STOPWORDS_NL = {
    "de", "het", "een", "en", "van", "ik", "je", "jij", "wij", "we", "dat", "die",
    "dit", "is", "zijn", "was", "waren", "op", "in", "voor", "met", "aan", "te", "om",
    "ook", "niet", "wel", "er", "maar", "dan", "als", "bij", "tot", "uit", "mijn", "onze",
    "hun", "uw", "nog", "meer", "veel", "heel", "wordt", "werden", "heb", "heeft", "hebben",
    "opleiding", "opleidingen", "student", "studenten", "school", "antwoord", "antwoorden",
    "vraag", "vragen",
}

STOPWORDS_EN = {
    "a", "an", "and", "are", "as", "at", "be", "been", "but", "by", "for", "from",
    "had", "has", "have", "he", "her", "his", "i", "in", "is", "it", "its", "me",
    "my", "not", "of", "on", "or", "our", "she", "that", "the", "their", "them",
    "there", "they", "this", "to", "was", "we", "were", "will", "with", "would", "you",
    "your",
}

METADATA_CANDIDATES = [
    "Opleidingsnaam", "Opleiding", "Instituut", "Opleidingsvorm", "Studiejaar",
    "Studiejaar student", "Croho", "Locatie", "Variant",
]


def normalize_token(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", str(value).lower())
    normalized = "".join(character for character in normalized if not unicodedata.combining(character))
    normalized = re.sub(r"[^a-z0-9]+", " ", normalized)
    return re.sub(r"\s+", " ", normalized).strip()


def normalize_sql_name(value: str) -> str:
    cleaned = re.sub(r"[^0-9a-zA-Z_]+", "_", value.strip())
    cleaned = re.sub(r"_+", "_", cleaned).strip("_").lower() or "sheet_1"
    return f"sheet_{cleaned}" if cleaned[0].isdigit() else cleaned


def is_low_value_answer(value: str) -> bool:
    normalized = normalize_token(value)
    return normalized in LOW_VALUE_ANSWERS or len(normalized) <= 1


def is_probably_dutch(value: str) -> bool:
    tokens = normalize_token(value).split()
    dutch_score = sum(token in STOPWORDS_NL for token in tokens)
    english_score = sum(token in STOPWORDS_EN for token in tokens)
    return dutch_score >= english_score


def looks_like_open_answer_column(column_name: str, series: pd.Series) -> bool:
    normalized_name = str(column_name).lower()
    keywords = [
        "meegeven", "toelichting", "opmerking", "opmerkingen", "feedback", "welzijn",
        "stage", "docent", "studiebegeleiding",
    ]
    if any(keyword in normalized_name for keyword in keywords):
        return True
    if not pd.api.types.is_string_dtype(series) and series.dtype != "object":
        return False
    values = series.dropna().astype(str).str.strip()
    values = values[values != ""]
    if values.empty:
        return False
    return values.str.len().mean() >= 20 and values.nunique() / len(values) >= 0.2


def normalize_open_answers(source: pd.DataFrame) -> tuple[pd.DataFrame, list[str], list[str]]:
    metadata_columns = [column for column in METADATA_CANDIDATES if column in source.columns]
    answer_columns = [
        column for column in source.columns if looks_like_open_answer_column(column, source[column])
    ]
    rows: list[dict] = []
    for response_row_id, source_row in source.reset_index(drop=True).iterrows():
        for question_column in answer_columns:
            raw_value = source_row.get(question_column)
            if pd.isna(raw_value):
                continue
            clean_value = str(raw_value).strip()
            if not clean_value:
                continue
            row = {
                "response_row_id": int(response_row_id),
                "question_column": question_column,
                "answer_raw": str(raw_value),
                "answer_clean": clean_value,
                "answer_length": len(clean_value),
            }
            row.update({column: source_row.get(column) for column in metadata_columns})
            rows.append(row)
    columns = [
        "response_row_id", "question_column", "answer_raw", "answer_clean", "answer_length",
        *metadata_columns,
    ]
    return pd.DataFrame(rows, columns=columns), answer_columns, metadata_columns

