def _requests_complete_list(question: str) -> bool:
    normalized = normalize_token(question)
    completeness = ("alle", "volledig", "volledige", "complete", "every", "all")
    collections = ("lijst", "overzicht", "waarden", "opleidingen", "instituten", "records", "rows")
    return any(token in normalized.split() for token in completeness) and any(
