def _load_table(connection: sqlite3.Connection, table: str) -> pd.DataFrame:
    return pd.read_sql_query(f'SELECT * FROM "{table}"', connection)


def _filtered_answers(frame: pd.DataFrame, question_column: str | None) -> pd.DataFrame:
    working = frame.copy()
    if question_column:
        working = working[working["question_column"] == question_column]
    return working[~working["answer_clean"].astype(str).map(is_low_value_answer)]


def _top_keywords(frame: pd.DataFrame, top_n: int) -> pd.DataFrame:
    counter = Counter()
    for answer in frame["answer_clean"].astype(str):
        for token in normalize_token(answer).split():
            if len(token) >= 4 and token not in STOPWORDS_NL:
                counter[token] += 1
    return pd.DataFrame([{"keyword": key, "count": count} for key, count in counter.most_common(top_n)])


def _requests_ngram_analysis(question: str) -> bool:
    normalized = normalize_token(question)
    indicators = ("n gram", "ngram", "bigram", "trigram", "woordcombinatie", "frase", "formulering")
    return any(indicator in normalized for indicator in indicators)


def _requests_unique_dutch_word_count(question: str) -> bool:
    normalized = normalize_token(question)
    return "unieke" in normalized.split() and "woorden" in normalized.split() and "hoeveel" in normalized.split()


def _analyze_deterministic(
    route: dict, source: pd.DataFrame, answers: pd.DataFrame, entities: pd.DataFrame,
    ngrams: pd.DataFrame, top_n: int, unique_dutch_word_count: int = 0
) -> tuple[pd.DataFrame, str]:
    route_name = route["route"]
    if route_name == "deterministic_unique_dutch_words":
        return pd.DataFrame([{"unique_dutch_word_count": unique_dutch_word_count}]), "unique Dutch word count"
    selected = route["question_column"]
    working = _filtered_answers(answers, selected)
    if route_name == "deterministic_ngrams":
        data = ngrams.copy()
        if selected and not data.empty and "question_column" in data:
            data = data[data["question_column"] == selected]
        if data.empty:
            return pd.DataFrame(), "frequent n-grams"
        result = data.groupby(["ngram", "n"], as_index=False).agg(
            document_frequency=("response_row_id", "nunique"),
            total_frequency=("response_row_id", "size"),
        ).sort_values(["document_frequency", "total_frequency"], ascending=False).head(top_n)
        return result, "frequent n-grams"
    if route_name == "special_case_studielast":
        column = QUESTION_COLUMN_BY_TOPIC["studielast"]
        if "Opleidingsvorm" not in source or column not in source:
            return pd.DataFrame(), "study-load comparison"
        data = source[["Opleidingsvorm", column]].dropna().copy()
        data = data[~data[column].astype(str).map(is_low_value_answer)]
        result = data.groupby("Opleidingsvorm").agg(answer_count=(column, "size"), example=(column, "first")).reset_index()
        return result, "study-load comparison"
    if route_name.startswith("deterministic_named_entities"):
        data = entities.copy()
        if selected:
            data = data[data["question_column"] == selected]
        if route["entity_label"]:
            data = data[data["entity_label"] == route["entity_label"]]
        if data.empty:
            return pd.DataFrame(), "spaCy named entities"
        result = data.groupby(["entity_text", "entity_label"]).agg(
            mention_count=("entity_text", "size"), answer_count=("response_row_id", "nunique")
        ).reset_index().sort_values(["mention_count", "answer_count"], ascending=False).head(top_n)
        return result, "spaCy named entities"
    if route_name == "deterministic_docenten_feedback":
        return working[["answer_clean"]].head(min(top_n, 50)), "teacher feedback"
    if route_name in {"deterministic_examples_by_subgroup"}:
        subgroup = route["subgroup"]
        if not subgroup or subgroup not in working:
            return pd.DataFrame(), "representative examples"
        result = working.groupby(subgroup).agg(
            answer_count=("answer_clean", "size"), representative_example=("answer_clean", "first")
        ).reset_index().sort_values("answer_count", ascending=False)
        return result, f"representative examples by {subgroup}"
    if route_name in {"deterministic_welzijn_by_subgroup", "deterministic_top_themes_by_subgroup"}:
        subgroup = route["subgroup"] or "Opleidingsvorm"
        rows = []
        if subgroup in working:
            for group, subset in working.groupby(subgroup, dropna=True):
                for item in _records(_top_keywords(subset, top_n=5)):
                    rows.append({subgroup: group, **item})
        return pd.DataFrame(rows), f"top themes by {subgroup}"
    return _top_keywords(working, top_n), "top keywords/themes"


def _result_markdown(frame: pd.DataFrame) -> str:
    if frame.empty:
        return "Geen resultaten gevonden."
    try:
        return frame.to_markdown(index=False)
    except ImportError:
        return frame.to_string(index=False)


def _azure_client(endpoint: str, api_key: str, api_version: str):
    from openai import AzureOpenAI
    return AzureOpenAI(azure_endpoint=endpoint, api_key=api_key, api_version=api_version)


def _willma_client(base_url: str, api_key: str):
    from openai import OpenAI
    return OpenAI(base_url=base_url, api_key=api_key)


def _chat_completion(messages: list[dict[str, str]], llm_config: dict[str, str]) -> str:
    provider = llm_config["provider"]
    if provider == "azure":
        client = _azure_client(
            llm_config["endpoint"], llm_config["api_key"], llm_config["api_version"]
        )
    elif provider == "willma":
        client = _willma_client(llm_config["endpoint"], llm_config["api_key"])
    else:
        raise ValueError(f"Unsupported LLM provider: {provider}")
    response = client.chat.completions.create(model=llm_config["model"], messages=messages)
    content = response.choices[0].message.content
    if not content or not content.strip():
        raise ValueError(f"{provider} returned an empty chat completion.")
    return content.strip()


def _generate_sql(
    question: str,
    dataset: dict,
    llm_config: dict[str, str],
    row_limit: int,
    previous_error: str = "",
) -> str:
    target_table = dataset["open_answers_table"] if dataset["route"] == "sql_open_answers_table" else dataset["source_table"]
    schema = dataset["open_answer_schema"] if target_table == dataset["open_answers_table"] else dataset["schema"]
    schema_text = "\n".join(f"- {item['column']} ({item['dtype']})" for item in schema)
    prompt = (
        "Return exactly one read-only SQLite SELECT query without Markdown. "
        "For a request for all values, select DISTINCT values and sort them; do not add a LIMIT. "
        f"Use only table {target_table} and these columns:\n{schema_text}\nQuestion: {question}"
    )
    if previous_error:
        prompt += (
            f"\nThe previous query failed with this SQLite error: {previous_error}. "
            "Correct it using only the listed columns."
        )
    response_text = _chat_completion([{"role": "user", "content": prompt}], llm_config)
    return validate_select(response_text, {target_table}, row_limit)


def _execute_generated_sql(
    question: str,
    dataset: dict,
    llm_config: dict[str, str],
    row_limit: int,
    connection: sqlite3.Connection,
) -> tuple[pd.DataFrame, str]:
    sql_query = _generate_sql(question, dataset, llm_config, row_limit)
    try:
        return pd.read_sql_query(sql_query, connection), sql_query
    except pd.errors.DatabaseError as error:
        if "no such column" not in str(error).lower():
            raise
        sql_query = _generate_sql(question, dataset, llm_config, row_limit, str(error))
        return pd.read_sql_query(sql_query, connection), sql_query


def _has_invalid_dutch_output(text: str) -> bool:
    unexpected_script = re.search(
        r"[\u3400-\u4dbf\u4e00-\u9fff\u3040-\u30ff\u0400-\u04ff]", text
    )
    return not text.strip() or "## Antwoord" not in text or "## Resultaat" not in text or bool(unexpected_script)


def _summarize_result(
    question: str,
    result_markdown: str,
    llm_config: dict[str, str],
) -> tuple[str, str]:
    summary_prompt = (
        "Vat dit analyseresultaat kort en feitelijk samen in correct Nederlands met exact de secties "
        "## Antwoord en ## Resultaat. Voeg geen feiten toe en citeer alleen begrijpelijke brontekst. "
        f"\nVraag: {question}\nResultaat:\n{result_markdown}"
    )
    draft = _chat_completion([{"role": "user", "content": summary_prompt}], llm_config)
    correction_prompt = (
        "Redigeer het concept hieronder naar helder, grammaticaal correct Nederlands. "
        "Behoud exact de koppen ## Antwoord en ## Resultaat. Gebruik uitsluitend feiten uit het "
        "bronresultaat, voeg niets toe, verwijder onbegrijpelijke tekst en gebruik geen Chinese, "
        "Japanse of Cyrillische tekens. Geef alleen de gecorrigeerde tekst."
        f"\n\nVraag:\n{question}\n\nBronresultaat:\n{result_markdown}\n\nConcept:\n{draft}"
    )
    corrected = _chat_completion([{"role": "user", "content": correction_prompt}], llm_config)
    if _has_invalid_dutch_output(corrected):
        fallback = (
            "## Antwoord\nDe automatische Nederlandse samenvatting kon niet betrouwbaar worden "
            "gecorrigeerd. Hieronder staat het ongewijzigde analyseresultaat."
            f"\n\n## Resultaat\n{result_markdown}"
        )
        return fallback, "raw result fallback after language validation"
    return corrected, "validated Dutch summary"


def answer_question(
    question: str,
    workbook_path: str,
    sheet_name: str = "",
    database_path: str = "",
    spacy_model: str = "nl_core_news_sm",
    ngram_min_n: int = 2,
    ngram_max_n: int = 3,
    ngram_minimum_frequency: int = 3,
    ngram_use_lemmas: bool = True,
    ngram_remove_stopwords: bool = True,
    azure_endpoint: str = "",
    azure_api_key: str = "",
    azure_api_version: str = "",
    azure_deployment: str = "",
    llm_provider: str = "azure",
    willma_base_url: str = "",
    willma_api_key: str = "",
    willma_model: str = "",
    include_summary: bool = True,
    top_n: int = 15,
) -> dict:
    if not question.strip():
        raise ValueError("Question cannot be empty.")
    settings = _project_settings()
    workbook_path = _setting(workbook_path, settings, "DATASET_PATH")
    database_path = _setting(database_path, settings, "EXCEL_OPEN_ANSWERS_DB_PATH")
    azure_endpoint = _setting(azure_endpoint, settings, "AZURE_OPENAI_ENDPOINT")
    azure_api_key = _setting(azure_api_key, settings, "AZURE_OPENAI_API_KEY")
    azure_api_version = _setting(
        azure_api_version, settings, "AZURE_OPENAI_API_VERSION", "2024-12-01-preview"
    )
    azure_deployment = _setting(
        azure_deployment,
        settings,
        "AZURE_OPENAI_DEPLOYMENT",
        settings.get("AZURE_OPENAI_MODEL", "o3-mini"),
    )
    llm_provider = str(llm_provider or "azure").strip().lower()
    willma_base_url = _setting(willma_base_url, settings, "WILLMA_BASE_URL", "https://api.willma.surf.nl/v0")
    willma_api_key = _setting(willma_api_key, settings, "WILLMA_API_KEY")
    willma_model = _setting(willma_model, settings, "WILLMA_MODEL")
    if llm_provider == "azure":
        llm_config = {
            "provider": "azure",
            "endpoint": azure_endpoint,
            "api_key": azure_api_key,
            "api_version": azure_api_version,
            "model": azure_deployment,
        }
    elif llm_provider == "willma":
        llm_config = {
            "provider": "willma",
            "endpoint": willma_base_url,
            "api_key": willma_api_key,
            "api_version": "",
            "model": willma_model,
        }
    else:
        raise ValueError("LLM Provider must be 'azure' or 'willma'.")
    if not workbook_path:
        raise ValueError("Set Workbook Path in the component or DATASET_PATH in the project .env file.")
    dataset = ensure_survey(workbook_path, sheet_name, database_path, spacy_model)
    dataset = ensure_ngram_tables(dataset, {
        "min_n": ngram_min_n,
        "max_n": ngram_max_n,
        "minimum_frequency": ngram_minimum_frequency,
        "use_lemmas": ngram_use_lemmas,
        "remove_stopwords": ngram_remove_stopwords,
    })
    route = route_question(question, dataset["open_answer_columns"])
    if _requests_ngram_analysis(question):
        route = {**route, "route": "deterministic_ngrams"}
    elif _requests_unique_dutch_word_count(question):
        route = {**route, "route": "deterministic_unique_dutch_words"}
    with sqlite3.connect(dataset["database_path"]) as connection:
        source = _load_table(connection, dataset["source_table"])
        answers = _load_table(connection, dataset["open_answers_table"])
        entities = _load_table(connection, dataset["spacy_entities_table"])
        ngrams = _load_table(connection, dataset["ngram_table"])
        if route["route"].startswith("sql_"):
            missing = [name for name in ("endpoint", "api_key", "model") if not llm_config[name]]
            if missing:
                raise ValueError(
                    f"Missing {llm_provider} settings for SQL fallback: {', '.join(missing)}"
                )
            context = {**dataset, **route, "open_answer_schema": _schema(answers)}
            exhaustive = _requests_complete_list(question)
            row_limit = EXHAUSTIVE_RESULT_LIMIT if exhaustive else top_n
            result, sql_query = _execute_generated_sql(
                question, context, llm_config, row_limit, connection
            )
            operation = "validated SQLite SELECT"
        else:
            exhaustive = False
            result, operation = _analyze_deterministic(
                route, source, answers, entities, ngrams, top_n,
                dataset.get("unique_dutch_word_count", 0),
            )
            sql_query = None
    result_markdown = _result_markdown(result)
    if exhaustive:
        final_answer = (
            f"## Antwoord\nAlle gevonden unieke waarden ({len(result)})."
            f"\n\n## Resultaat\n{result_markdown}"
        )
    elif include_summary and llm_config["endpoint"] and llm_config["api_key"] and llm_config["model"]:
        final_answer, summary_status = _summarize_result(question, result_markdown, llm_config)
        operation = f"{operation}; {summary_status}"
    else:
        final_answer = f"## Antwoord\nAnalyse uitgevoerd via `{route['route']}`.\n\n## Resultaat\n{result_markdown}"
    return {
        "question": question,
        "route": route["route"],
        "selected_question_column": route["question_column"],
        "sql_query": sql_query,
        "diagnostics": {**route, "operation": operation, "database_path": dataset["database_path"]},
        "rows": _records(result),
        "result_markdown": result_markdown,
        "final_answer": final_answer,
    }

from langflow.custom import Component
from langflow.io import DataInput, Output
from langflow.schema import Data

class BuildNgramTablesComponent(Component):
    display_name = "Build N-gram Tables"
    description = "Extracts frequent word n-grams and persists occurrence and summary tables in SQLite."
    icon = "Table2"
    name = "BuildNgramTables"

    inputs = [
        DataInput(name="dataset", display_name="NER Dataset", required=True),
        DataInput(name="ngram_config", display_name="N-gram Configuration", required=True),
    ]
    outputs = [Output(name="enriched_dataset", display_name="N-gram Dataset", method="build_tables")]

    def build_tables(self) -> Data:
        dataset = ensure_ngram_tables(self.dataset.data, self.ngram_config.data)
        self.status = f"{dataset['ngram_cache_status'].title()} {dataset['ngram_count']} n-grams"
        return Data(data=dataset)

import re
import unicodedata

import pandas as pd


LOW_VALUE_ANSWERS = {
    "", "-", ".", "...", "nvt", "n.v.t.", "nee", "geen", "geen opmerkingen",
    "geen opmerking", "niks", "niets", "nope",
}

STOPWORDS_NL = {
    "de", "het", "een", "en", "van", "ik", "je", "jij", "wij", "we", "dat", "die",
    "dit", "is", "zijn", "was", "waren", "op", "in", "voor", "met", "aan", "te", "om",
    "ook", "niet", "wel", "er", "maar", "dan", "als", "bij", "tot", "uit", "mijn", "onze",
    "hun", "uw", "nog", "meer", "veel", "heel", "wordt", "werden", "heb", "heeft", "hebben",
    "opleiding", "opleidingen", "student", "studenten", "school", "antwoord", "antwoorden",
    "vraag", "vragen",
}

STOPWORDS_EN = {
    "a", "an", "and", "are", "as", "at", "be", "been", "but", "by", "for", "from",
    "had", "has", "have", "he", "her", "his", "i", "in", "is", "it", "its", "me",
    "my", "not", "of", "on", "or", "our", "she", "that", "the", "their", "them",
    "there", "they", "this", "to", "was", "we", "were", "will", "with", "would", "you",
    "your",
}

METADATA_CANDIDATES = [
    "Opleidingsnaam", "Opleiding", "Instituut", "Opleidingsvorm", "Studiejaar",
    "Studiejaar student", "Croho", "Locatie", "Variant",
]


def normalize_token(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", str(value).lower())
    normalized = "".join(character for character in normalized if not unicodedata.combining(character))
    normalized = re.sub(r"[^a-z0-9]+", " ", normalized)
    return re.sub(r"\s+", " ", normalized).strip()


def normalize_sql_name(value: str) -> str:
    cleaned = re.sub(r"[^0-9a-zA-Z_]+", "_", value.strip())
    cleaned = re.sub(r"_+", "_", cleaned).strip("_").lower() or "sheet_1"
    return f"sheet_{cleaned}" if cleaned[0].isdigit() else cleaned


def is_low_value_answer(value: str) -> bool:
    normalized = normalize_token(value)
    return normalized in LOW_VALUE_ANSWERS or len(normalized) <= 1


def is_probably_dutch(value: str) -> bool:
    tokens = normalize_token(value).split()
    dutch_score = sum(token in STOPWORDS_NL for token in tokens)
    english_score = sum(token in STOPWORDS_EN for token in tokens)
    return dutch_score >= english_score


def looks_like_open_answer_column(column_name: str, series: pd.Series) -> bool:
    normalized_name = str(column_name).lower()
    keywords = [
        "meegeven", "toelichting", "opmerking", "opmerkingen", "feedback", "welzijn",
        "stage", "docent", "studiebegeleiding",
    ]
    if any(keyword in normalized_name for keyword in keywords):
        return True
    if not pd.api.types.is_string_dtype(series) and series.dtype != "object":
        return False
    values = series.dropna().astype(str).str.strip()
    values = values[values != ""]
    if values.empty:
        return False
    return values.str.len().mean() >= 20 and values.nunique() / len(values) >= 0.2


def normalize_open_answers(source: pd.DataFrame) -> tuple[pd.DataFrame, list[str], list[str]]:
    metadata_columns = [column for column in METADATA_CANDIDATES if column in source.columns]
    answer_columns = [
        column for column in source.columns if looks_like_open_answer_column(column, source[column])
    ]
    rows: list[dict] = []
    for response_row_id, source_row in source.reset_index(drop=True).iterrows():
        for question_column in answer_columns:
            raw_value = source_row.get(question_column)
            if pd.isna(raw_value):
                continue
            clean_value = str(raw_value).strip()
            if not clean_value:
                continue
            row = {
                "response_row_id": int(response_row_id),
                "question_column": question_column,
                "answer_raw": str(raw_value),
                "answer_clean": clean_value,
                "answer_length": len(clean_value),
            }
            row.update({column: source_row.get(column) for column in metadata_columns})
            rows.append(row)
    columns = [
        "response_row_id", "question_column", "answer_raw", "answer_clean", "answer_length",
        *metadata_columns,
    ]
    return pd.DataFrame(rows, columns=columns), answer_columns, metadata_columns

import re



QUESTION_COLUMN_BY_TOPIC = {
    "stages": "Wil jij je opleiding nog iets meegeven over de aansluiting op de beroepspraktijk / beroepsloopbaan?",
    "studiebegeleiding": "Wil jij je opleiding nog iets meegeven over de aansluiting op de beroepspraktijk / beroepsloopbaan?",
    "studielast": "Wil jij je opleiding nog iets meegeven over de studielast?",
    "docenten": "Wil jij je opleiding nog iets meegeven over de inhoud en opzet van het onderwijs?",
    "welzijn": "Wil jij je opleiding nog iets meegeven over de inhoud en opzet van het onderwijs?",
    "onderwijs": "Wil jij je opleiding nog iets meegeven over de inhoud en opzet van het onderwijs?",
}

QUESTION_TOPIC_ALIASES = {
    "stages": ["stage", "stages", "stageplek", "beroepspraktijk", "beroepsloopbaan", "praktijk"],
    "studiebegeleiding": ["studiebegeleiding", "begeleiding", "coach", "slb", "studieloopbaan"],
    "studielast": ["studielast", "werkdruk", "belasting", "deadlines"],
    "docenten": ["docent", "docenten", "leraar", "leraren"],
    "welzijn": ["welzijn", "welbevinden", "mentaal", "stress", "gezondheid"],
    "onderwijs": ["onderwijs", "inhoud", "opzet", "lessen", "curriculum"],
}

NER_PATTERN = re.compile(
    r"\b(?:entiteit|entiteiten|organisatie|organisaties|persoon|personen|locatie|locaties)\b"
)


def infer_topic(question: str) -> str | None:
    normalized = normalize_token(question)
    scores = {
        topic: sum(alias in normalized for alias in aliases)
        for topic, aliases in QUESTION_TOPIC_ALIASES.items()
    }
    topic, score = max(scores.items(), key=lambda item: item[1])
    return topic if score else None


def choose_question_column(question: str, available_columns: list[str]) -> str | None:
    topic = infer_topic(question)
    mapped = QUESTION_COLUMN_BY_TOPIC.get(topic) if topic else None
    if mapped in available_columns:
        return mapped
    normalized_question = normalize_token(question)
    scored = []
    for column in available_columns:
        score = sum(token in normalized_question for token in normalize_token(column).split())
        if score:
            scored.append((score, column))
    return max(scored)[1] if scored else None


def infer_entity_label(question: str) -> str | None:
    normalized = normalize_token(question)
    has_person = any(token in normalized for token in ["persoon", "personen"])
    has_org = any(token in normalized for token in ["organisatie", "organisaties", "bedrijf", "bedrijven"])
    if has_person and has_org:
        return None
    if has_person:
        return "PER"
    if has_org:
        return "ORG"
    if any(token in normalized for token in ["locatie", "locaties", "plaats", "stad", "land"]):
        return "LOC"
    return None


def infer_entity_source(question: str) -> str:
    normalized = normalize_token(question)
    if "azure" in normalized and "spacy" in normalized:
        return "compare"
    if "azure" in normalized:
        return "azure"
    return "spacy"


def infer_subgroup(question: str) -> str | None:
    normalized = normalize_token(question)
    for phrase, column in [
        ("per instituut", "Instituut"),
        ("per opleidingsvorm", "Opleidingsvorm"),
        ("per studiejaar", "Studiejaar"),
        ("per opleiding", "Opleiding"),
    ]:
        if phrase in normalized:
            return column
    return None


def route_question(question: str, available_columns: list[str]) -> dict:
    normalized = normalize_token(question)
    selected_column = choose_question_column(question, available_columns)
    entity_source = infer_entity_source(question)
    subgroup = infer_subgroup(question)
    if "voltijd" in normalized and "deeltijd" in normalized and "studielast" in normalized:
        route = "special_case_studielast"
    elif NER_PATTERN.search(normalized):
        route = f"deterministic_named_entities_{entity_source}"
    elif any(token in normalized for token in ["docent", "docenten", "leraar", "leraren"]):
        route = "deterministic_docenten_feedback"
    elif "welzijn" in normalized and subgroup:
        route = "deterministic_welzijn_by_subgroup"
    elif any(token in normalized for token in ["voorbeeld", "voorbeelden"]) and subgroup:
        route = "deterministic_examples_by_subgroup"
    elif "thema" in normalized:
        route = "deterministic_top_themes_by_subgroup" if subgroup else "deterministic_top_themes"
    elif any(token in normalized for token in ["keyword", "keywords", "sleutelwoord", "woorden"]):
        route = "deterministic_top_keywords"
    else:
        open_answer_signal = selected_column is not None or any(
            token in normalized for token in ["open antwoord", "feedback", "opmerking", "welzijn", "stage"]
        )
        route = "sql_open_answers_table" if open_answer_signal else "sql_main_table"
    return {
        "question": question,
        "route": route,
        "topic": infer_topic(question),
        "question_column": selected_column,
        "entity_label": infer_entity_label(question),
        "entity_source": entity_source,
        "subgroup": subgroup,
    }

import re


FORBIDDEN_SQL = re.compile(
    r"\b(?:insert|update|delete|drop|alter|attach|detach|pragma|vacuum|replace|create|truncate)\b",
    re.IGNORECASE,
)


def validate_select(sql: str, allowed_tables: set[str], row_limit: int = 200) -> str:
    query = sql.strip().removeprefix("```sql").removeprefix("```").removesuffix("```").strip()
    if ";" in query.rstrip(";") or "--" in query or "/*" in query:
        raise ValueError("SQL comments and multiple statements are not allowed.")
    query = query.rstrip(";").strip()
    if not re.match(r"^(select|with)\b", query, re.IGNORECASE) or FORBIDDEN_SQL.search(query):
        raise ValueError("Only a single read-only SELECT query is allowed.")
    referenced = set(re.findall(r"\b(?:from|join)\s+[\[\"`]?([\w]+)", query, re.IGNORECASE))
    if not referenced or not referenced.issubset(allowed_tables):
        raise ValueError(f"Query references an unavailable table: {sorted(referenced - allowed_tables)}")
    if not re.search(r"\blimit\s+\d+\b", query, re.IGNORECASE):
        query = f"{query}\nLIMIT {int(row_limit)}"
    return query

